// doc_id: doc_other_0009 — generated by generate-tab-childpanels.js (M33)
// @spec-source → WBS v6 OPEN-10（紅顏池展示畫面，接在轉蛋 Support 分頁下方）；PROG-2-0472
//
// GachaDs3SupportChild — UCUF ChildPanel for tab "Support".
// Wire this into the CompositePanel's _switchToTab routing table.
//
// 紅顏展示區接在既有內容下方（fragment 節點 redFaceShowcaseRoot）。
// 節點 name 與 RedFaceShowcaseController 的 flow key 一一對應，點列只呼叫 select()。

import { Button } from 'cc';
import { ChildPanelBase } from '../../core/ChildPanelBase';
import type { UISkinResolver } from '../../core/UISkinResolver';
import type { UITemplateBinder } from '../../core/UITemplateBinder';
import { applyFlowView } from '../../core/NurtureFlowViewApplier';
import {
    RED_FACE_SHOW_MAX_ROWS,
    RedFaceShowcaseController,
    toRedFaceTabFlowView,
} from '../../core/RedFaceShowcaseController';
import { UCUFLogger, LogCategory } from '../../../core/utils/UCUFLogger';

export class GachaDs3SupportChild extends ChildPanelBase {
    override dataSource = 'config';
    private static readonly ROOT_PATH = 'TabSupportContent';

    private _binder: UITemplateBinder | null = null;
    private _redFace: RedFaceShowcaseController | null = null;

    /** 由轉蛋畫面注入紅顏展示控制器（資料來源在呼叫端，不在此處讀檔）。 */
    public attachRedFace(controller: RedFaceShowcaseController): void {
        this._redFace = controller;
        this._refreshRedFace();
    }

    public override onMount(binder: UITemplateBinder, _skin: UISkinResolver): void {
        UCUFLogger.info(LogCategory.LIFECYCLE, '[GachaDs3SupportChild] onMount', { rootPath: GachaDs3SupportChild.ROOT_PATH });
        this._binder = binder;
        for (let i = 0; i < RED_FACE_SHOW_MAX_ROWS; i++) {
            const button = binder.getButton(`btnRedFaceRow${i}`);
            if (!button) continue;
            button.node.off(Button.EventType.CLICK);
            button.node.on(Button.EventType.CLICK, () => this._selectRedFace(i), this);
        }
        this._refreshRedFace();
    }

    public override onDataChanged(_data: unknown): void {
        this._refreshRedFace();
    }

    public override onUnmount(): void {
        this._binder = null;
    }

    private _selectRedFace(index: number): void {
        this._redFace?.select(index);
        this._refreshRedFace();
    }

    private _refreshRedFace(): void {
        if (!this._binder || !this._redFace) return;
        applyFlowView(this._binder, toRedFaceTabFlowView(this._redFace.getFlowView()));
    }
}
